-- Product ownership is separate from hub_rules.scope (which means seller).
-- No seed, raw/source mutation, baseline commit or production resolver cutover.
CREATE OR REPLACE FUNCTION operations_private.hub_sku_input_fingerprint_v1(p_sku text, p_source text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare codes text[]; body jsonb; sellpia_id uuid; trace jsonb;
begin
 if length(coalesce(p_sku,'')) not between 1 and 128 or p_source is null or p_source not in ('','smartstore','makeshop','ably') then raise exception 'invalid fingerprint scope';end if;
 codes:=operations_private.hub_input_scope_v1(p_sku,p_source);
 with recursive active as (select a.*,r.source_field,r.source_scope,r.input_origin from operations_private.hub_rule_assignments a join operations_private.hub_rules r on r.id=a.rule_id where r.is_active),
 seeds(sku,field,scope) as (
  select s,'calculated_base_price','' from unnest(codes) s
  union select s,f,p_source from unnest(codes) s cross join (values ('platform_registration_price'),('platform_discount_price'),('platform_option_price'),('platform_final_price')) x(f) where p_source<>''
  union select a.sku,a.target_field,'' from active a where a.sku=any(codes) and a.scope='' and p_source=''
 ), nodes(sku,field,scope) as (
  select * from seeds union
  select case when a.input_origin='parent' then ref.parent_sku else n.sku end,
   case when a.rule_id is not null then case when a.input_origin='parent' then ref.source_field else a.source_field end
    when n.field='calculated_base_price' then 'basis_sku_price' else 'actual_inbound_cost' end,
   case when a.rule_id is not null and (case when a.input_origin='parent' then ref.source_field else a.source_field end) like 'platform_%' then coalesce(nullif(ref.source_scope,''),nullif(a.source_scope,''),a.scope) else '' end
  from nodes n left join active a on a.sku=n.sku and a.target_field=n.field and a.scope=n.scope left join operations_private.hub_field_references ref on ref.child_sku=a.sku and ref.rule_id=a.rule_id
  where a.rule_id is not null or n.scope='' and n.field='basis_sku_price' and exists(select 1 from active b where b.sku=n.sku and b.scope='' and b.target_field='actual_inbound_cost')
   or n.scope='' and n.field='calculated_base_price' and exists(select 1 from active b where b.sku=n.sku and b.scope='' and b.target_field in ('actual_inbound_cost','basis_sku_price'))
 ) select jsonb_agg(jsonb_build_object('sku',sku,'field',field,'scope',scope) order by sku,scope,field) into trace from nodes;
 select snapshot_id into sellpia_id from public.sellpia_stock_snapshots where upload_status='ready' order by coalesce(completed_at,created_at) desc,created_at desc,snapshot_id desc limit 1;
 body:=jsonb_build_object('contract','hub-input-v1','source',p_source,'codes',codes,
  'trace',trace,
  'cache',(select coalesce(jsonb_agg(jsonb_build_object('sku',c.sellpia_sku_code,'input_base',case when not exists(select 1 from operations_private.hub_rule_assignments a join operations_private.hub_rules r on r.id=a.rule_id where a.sku=c.sellpia_sku_code and a.scope='' and r.is_active and a.target_field in ('actual_inbound_cost','basis_sku_price','calculated_base_price')) then to_jsonb(c)->'system_base_price' end,'input_stock',case when exists(select 1 from jsonb_array_elements(trace) n where n->>'sku'=c.sellpia_sku_code and n->>'field' in ('system_stock','calculated_stock')) then to_jsonb(c)->'system_stock' end,'identity',(select jsonb_object_agg(k,v) from jsonb_each(to_jsonb(c)) kv(k,v) where k like '%\_product_code' escape '\' or k like '%\_option_code' escape '\' or k like '%\_listing_count' escape '\')) order by c.sellpia_sku_code),'[]') from operations_private.operations_hub_matrix_export_cache c where c.sellpia_sku_code=any(codes)),
  'raw',(select coalesce(jsonb_agg(jsonb_build_object('sku',r.sellpia_sku_code,'purchase',case when exists(select 1 from jsonb_array_elements(trace) n where n->>'sku'=r.sellpia_sku_code and n->>'field'='purchase_price') then to_jsonb(r.purchase_price) end,'base',case when exists(select 1 from jsonb_array_elements(trace) n where n->>'sku'=r.sellpia_sku_code and n->>'field'='source_base_price') then r.raw_payload->'base_price' end) order by r.sellpia_sku_code),'[]') from public.sellpia_stock_snapshot_rows r where r.snapshot_id=sellpia_id and r.sellpia_sku_code=any(codes)),
  'master',(select coalesce(jsonb_agg(jsonb_build_object('sku',m.sellpia_sku_code,'base',case when exists(select 1 from jsonb_array_elements(trace) n where n->>'sku'=m.sellpia_sku_code and n->>'field' in ('basis_sku_price','calculated_base_price') and not exists(select 1 from operations_private.hub_rule_assignments a join operations_private.hub_rules ru on ru.id=a.rule_id where a.sku=m.sellpia_sku_code and a.scope='' and ru.is_active)) then to_jsonb(m.base_price) end,'stock',case when exists(select 1 from jsonb_array_elements(trace) n where n->>'sku'=m.sellpia_sku_code and n->>'field' in ('system_stock','calculated_stock')) then to_jsonb(m.stock_quantity) end,'purchase',case when exists(select 1 from jsonb_array_elements(trace) n where n->>'sku'=m.sellpia_sku_code and n->>'field'='purchase_price') then to_jsonb(m.purchase_price) end) order by m.sellpia_sku_code),'[]') from public.operations_hub_sku_operational_master m where m.sellpia_sku_code=any(codes)),
  'inbound',(select coalesce(jsonb_agg(jsonb_build_object('sku',s.sellpia_sku_code,'manual',s.manual_cost,'tag',to_jsonb(t)-'updated_at'-'created_at'-'created_by'-'updated_by') order by s.sellpia_sku_code),'[]') from public.operations_hub_inbound_cost_settings s left join public.operations_hub_inbound_cost_formula_tags t on t.tag_id=s.formula_tag_id where s.sellpia_sku_code=any(codes)),
  'rules',(select coalesce(jsonb_agg(jsonb_build_object('sku',a.sku,'assignment',to_jsonb(a)-'updated_at'-'updated_by','rule',to_jsonb(r)-'updated_at'-'updated_by') order by a.sku,a.scope,a.target_field),'[]') from operations_private.hub_rule_assignments a join operations_private.hub_rules r on r.id=a.rule_id where a.sku=any(codes) and r.is_active),
  'refs',(select coalesce(jsonb_agg(to_jsonb(e)||jsonb_build_object('relation_valid',e.relation_edge_id is null or exists(select 1 from public.operations_hub_relation_edges re join public.operations_hub_relation_nodes pn on pn.node_id=re.parent_node_id join public.operations_hub_relation_nodes cn on cn.node_id=re.child_node_id where re.edge_id=e.relation_edge_id and re.is_active and pn.is_active and cn.is_active and pn.sellpia_sku_code=e.parent_sku and cn.sellpia_sku_code=e.child_sku)) order by e.child_sku,e.scope,e.target_field),'[]') from operations_private.hub_field_references e where e.child_sku=any(codes)),
  'policy',(select coalesce(jsonb_agg(jsonb_build_object('title',d.title,'body',d.body,'version',d.version) order by d.title),'[]') from operations_private.hub_work_documents d where d.kind='formula' and (d.title='registry-platform:'||p_source or exists(select 1 from jsonb_array_elements(trace) n where d.title='registry-platform:'||(n->>'scope') and n->>'field' like 'platform_%'))),
  'drafts',(select coalesce(jsonb_agg(to_jsonb(q)-'updated_at'-'created_at' order by q.change_id),'[]') from public.operations_hub_change_queue q where q.sellpia_sku_code=any(codes) and q.field_key='sellpia_sale_price' and q.status in ('pending','validated','processing')),
  'seller_raw',(select coalesce(jsonb_agg(jsonb_build_object('sku',c.sellpia_sku_code,'source',s.source_channel,'row',jsonb_build_object('product_code',r.product_code,'option_code',r.option_code,'base',r.base_price,'discounted',r.discounted_base_price,'option',r.option_price,'final',r.final_price,'terms',r.discount_terms)) order by c.sellpia_sku_code,s.source_channel,r.product_code,r.option_code),'[]') from operations_private.operations_hub_matrix_export_cache c cross join lateral (select distinct on (source_channel) snapshot_id,source_channel from public.seller_inventory_snapshots where upload_status='ready' order by source_channel,coalesce(completed_at,created_at) desc,created_at desc,snapshot_id desc) s join public.seller_inventory_snapshot_rows r on r.snapshot_id=s.snapshot_id and r.product_code=to_jsonb(c)->>(s.source_channel||'_product_code') and coalesce(r.option_code,'')=coalesce(to_jsonb(c)->>(s.source_channel||'_option_code'),'') where c.sellpia_sku_code=any(codes) and (s.source_channel=p_source or exists(select 1 from jsonb_array_elements(trace) n where n->>'scope'=s.source_channel and n->>'field' like 'platform_%')))
 );
 return encode(extensions.digest(body::text,'sha256'),'hex');
end $function$
;

CREATE OR REPLACE FUNCTION operations_private.hub_sku_rule_lineage_valid_v1(p_sku text, p_source text, p_versions jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare codes text[];trace jsonb;
begin
 if jsonb_typeof(p_versions) is distinct from 'array' or jsonb_array_length(p_versions) not between 1 and 512 then return false;end if;
 codes:=operations_private.hub_input_scope_v1(p_sku,p_source);
 with recursive active as (select a.*,r.source_field,r.source_scope,r.input_origin from operations_private.hub_rule_assignments a join operations_private.hub_rules r on r.id=a.rule_id where r.is_active),
 seeds(sku,field,scope) as (
  select s,'calculated_base_price','' from unnest(codes) s
  union select s,f,p_source from unnest(codes) s cross join (values ('platform_registration_price'),('platform_discount_price'),('platform_option_price'),('platform_final_price')) x(f) where p_source<>''
  union select a.sku,a.target_field,'' from active a where a.sku=any(codes) and a.scope='' and p_source=''
 ), nodes(sku,field,scope) as (
  select * from seeds union
  select case when a.input_origin='parent' then ref.parent_sku else n.sku end,
   case when a.rule_id is not null then case when a.input_origin='parent' then ref.source_field else a.source_field end
    when n.field='calculated_base_price' then 'basis_sku_price' else 'actual_inbound_cost' end,
   case when a.rule_id is not null and (case when a.input_origin='parent' then ref.source_field else a.source_field end) like 'platform_%' then coalesce(nullif(ref.source_scope,''),nullif(a.source_scope,''),a.scope) else '' end
  from nodes n left join active a on a.sku=n.sku and a.target_field=n.field and a.scope=n.scope left join operations_private.hub_field_references ref on ref.child_sku=a.sku and ref.rule_id=a.rule_id
  where a.rule_id is not null or n.scope='' and n.field='basis_sku_price' and exists(select 1 from active b where b.sku=n.sku and b.scope='' and b.target_field='actual_inbound_cost')
   or n.scope='' and n.field='calculated_base_price' and exists(select 1 from active b where b.sku=n.sku and b.scope='' and b.target_field in ('actual_inbound_cost','basis_sku_price'))
 ) select jsonb_agg(jsonb_build_object('sku',sku,'field',field,'scope',scope) order by sku,scope,field) into trace from nodes;

 -- Only actual active field references can authorize parent Rule versions.
 if exists(select 1 from jsonb_array_elements(trace) n join operations_private.hub_rule_assignments a on a.sku=n->>'sku' and a.scope=n->>'scope' and a.target_field=n->>'field' join operations_private.hub_rules r on r.id=a.rule_id
  left join operations_private.hub_field_references ref on ref.child_sku=a.sku and ref.rule_id=a.rule_id and ref.scope=a.scope and ref.target_field=a.target_field
  where r.is_active and r.input_origin='parent' and (ref.parent_sku is null or ref.relation_edge_id is not null and not exists(select 1 from public.operations_hub_relation_edges e join public.operations_hub_relation_nodes pn on pn.node_id=e.parent_node_id join public.operations_hub_relation_nodes cn on cn.node_id=e.child_node_id where e.edge_id=ref.relation_edge_id and e.is_active and pn.is_active and cn.is_active and pn.sellpia_sku_code=ref.parent_sku and cn.sellpia_sku_code=ref.child_sku))) then return false;end if;
 if exists(select 1 from jsonb_array_elements(p_versions) rv where not exists(
  select 1 from jsonb_array_elements(trace) n join operations_private.hub_rule_assignments a on a.sku=n->>'sku' and a.scope=n->>'scope' and a.target_field=n->>'field'
   join operations_private.hub_rules r on r.id=a.rule_id where r.is_active and r.scope=a.scope and r.target_field=a.target_field
   and r.id::text=rv->>'id' and r.version::text=rv->>'version' and a.version::text=rv->>'assignmentVersion'
 )) then return false;end if;
 -- Root seller price instruction must be present in its own recorded provenance.
 return exists(select 1 from operations_private.hub_rule_assignments a join operations_private.hub_rules r on r.id=a.rule_id
  join jsonb_array_elements(p_versions) rv on rv->>'id'=r.id::text and rv->>'version'=r.version::text and rv->>'assignmentVersion'=a.version::text
  where a.sku=p_sku and a.scope=p_source and r.is_active and r.target_field like 'platform_%');
end $function$
;
create table operations_private.hub_product_price_rules(
 id uuid primary key default gen_random_uuid(), tag_id uuid not null references public.product_tags(tag_id),
 selection text not null check(selection in ('lowest','lower_middle','direct')),
 version integer not null default 1 check(version>0), is_active boolean not null default true,
 updated_at timestamptz not null default clock_timestamp(), updated_by text not null
);
create unique index hub_product_price_rule_tag_owner on operations_private.hub_product_price_rules(tag_id) where is_active;
create table operations_private.hub_product_price_assignments(
 assignment_id uuid not null default gen_random_uuid(),
 product_code text primary key check(length(product_code) between 1 and 200),
 rule_id uuid not null references operations_private.hub_product_price_rules(id),
 version integer not null default 1 check(version>0), direct_identity jsonb,
 updated_at timestamptz not null default clock_timestamp(), updated_by text not null
);
create table operations_private.hub_product_price_results(
 id uuid primary key default gen_random_uuid(), product_code text not null,
 generation_id bigint not null references operations_private.hub_calculation_generations(generation_id),
 value numeric check(value between 0 and 9007199254740991 and value=trunc(value)),
 status text not null check(status in ('calculated','stale','blocked')),
 input_fingerprint text not null, proof jsonb not null,
 calculated_at timestamptz not null default clock_timestamp(),
 check((status='calculated')=(value is not null))
);
create index hub_product_price_history on operations_private.hub_product_price_results(product_code,calculated_at desc);
create table operations_private.hub_product_price_result_heads(
 product_code text primary key, result_id uuid not null references operations_private.hub_product_price_results(id)
);
alter table operations_private.hub_product_price_rules enable row level security;
alter table operations_private.hub_product_price_assignments enable row level security;
alter table operations_private.hub_product_price_results enable row level security;
alter table operations_private.hub_product_price_result_heads enable row level security;
revoke all on operations_private.hub_product_price_rules,operations_private.hub_product_price_assignments,operations_private.hub_product_price_results,operations_private.hub_product_price_result_heads from public,anon,authenticated;

alter table operations_private.hub_rules drop constraint hub_rules_source_field_check;
alter table operations_private.hub_rules add constraint hub_rules_source_field_check check(source_field in
 ('purchase_price','source_base_price','actual_inbound_cost','basis_sku_price','calculated_base_price','system_stock','calculated_stock','platform_registration_price','platform_option_price','platform_discount_price','platform_final_price','platform_price','platform_option_input','platform_final_input','representative_base_price'));
alter table operations_private.hub_rules add constraint hub_rules_representative_input_check check(source_field<>'representative_base_price' or
 (target_field='platform_registration_price' and input_origin='self' and scope in ('smartstore','makeshop','ably') and source_scope=''));

-- Returns only the actual internal base dependency path, not unrelated tags.
create function operations_private.hub_base_rule_trace_v1(p_sku text)
returns jsonb language sql stable set search_path=pg_catalog as $$
 with recursive active as (
  select a.*,r.input_origin,r.source_field,r.source_scope,r.version rule_version,r.tag_id,
   ref.parent_sku,ref.source_field parent_field,ref.source_scope parent_scope,ref.relation_edge_id
  from operations_private.hub_rule_assignments a join operations_private.hub_rules r on r.id=a.rule_id
  join public.product_tags t on t.tag_id=r.tag_id and t.is_active
  left join operations_private.hub_field_references ref on ref.child_sku=a.sku and ref.rule_id=a.rule_id and ref.target_field=a.target_field and ref.scope=a.scope
  where r.is_active and r.scope=a.scope and r.target_field=a.target_field
 ), nodes(sku,field,scope) as (
  select p_sku,'calculated_base_price'::text,''::text union
  select case when a.input_origin='parent' then a.parent_sku else n.sku end,
   case when a.rule_id is not null then case when a.input_origin='parent' then a.parent_field else a.source_field end
    when n.field='calculated_base_price' then 'basis_sku_price' else 'actual_inbound_cost' end,
   case when coalesce(a.parent_field,a.source_field) like 'platform_%' then coalesce(nullif(a.parent_scope,''),nullif(a.source_scope,''),a.scope) else '' end
  from nodes n left join active a on a.sku=n.sku and a.target_field=n.field and a.scope=n.scope
  where a.rule_id is not null or n.scope='' and n.field='calculated_base_price' and exists(select 1 from active b where b.sku=n.sku and b.scope='' and b.target_field in ('basis_sku_price','actual_inbound_cost'))
   or n.scope='' and n.field='basis_sku_price' and exists(select 1 from active b where b.sku=n.sku and b.scope='' and b.target_field='actual_inbound_cost')
 ) select coalesce(jsonb_agg(jsonb_build_object('sku',a.sku,'id',a.rule_id,'version',a.rule_version,'assignmentVersion',a.version,
  'parent_valid',a.input_origin<>'parent' or a.parent_sku is not null and (a.relation_edge_id is null or exists(
   select 1 from public.operations_hub_relation_edges e join public.operations_hub_relation_nodes pn on pn.node_id=e.parent_node_id join public.operations_hub_relation_nodes cn on cn.node_id=e.child_node_id
   where e.edge_id=a.relation_edge_id and e.is_active and pn.is_active and cn.is_active and pn.sellpia_sku_code=a.parent_sku and cn.sellpia_sku_code=a.sku))) order by a.sku,a.rule_id),'[]')
 from nodes n join active a on a.sku=n.sku and a.target_field=n.field and a.scope=n.scope
$$;
create function operations_private.hub_base_lineage_valid_v1(p_sku text,p_versions jsonb)
returns boolean language plpgsql stable set search_path=pg_catalog as $$
declare trace jsonb;
begin
 if jsonb_typeof(p_versions) is distinct from 'array' or jsonb_array_length(p_versions) not between 1 and 512 then return false;end if;
 trace:=operations_private.hub_base_rule_trace_v1(p_sku);
 if exists(select 1 from jsonb_array_elements(trace) t join operations_private.hub_rules r on r.id::text=t->>'id' where r.source_field='representative_base_price') then return false;end if;
 if jsonb_array_length(trace)=0 or exists(select 1 from jsonb_array_elements(trace) t where t->>'parent_valid'<>'true') then return false;end if;
 return not exists(select 1 from jsonb_array_elements(trace) t where not exists(select 1 from jsonb_array_elements(p_versions) v where v->>'id'=t->>'id' and v->>'version'=t->>'version' and v->>'assignmentVersion'=t->>'assignmentVersion'))
 and not exists(select 1 from jsonb_array_elements(p_versions) v where not exists(select 1 from jsonb_array_elements(trace) t where v->>'id'=t->>'id' and v->>'version'=t->>'version' and v->>'assignmentVersion'=t->>'assignmentVersion'));
end $$;

-- Full membership comes from Sellpia, never from seller carrier subsets.
create function operations_private.hub_product_price_inputs_v1(p_product text)
returns jsonb language plpgsql stable set search_path=pg_catalog as $$
declare owner jsonb; members jsonb; issues jsonb:='[]'; body jsonb; item jsonb; n integer;
begin
 select to_jsonb(a)||jsonb_build_object('tag_id',r.tag_id,'tag_name',t.tag_name,'selection',r.selection,'rule_version',r.version)
 into owner from operations_private.hub_product_price_assignments a join operations_private.hub_product_price_rules r on r.id=a.rule_id and r.is_active
 join public.product_tags t on t.tag_id=r.tag_id and t.is_active where a.product_code=p_product;
 select coalesce(jsonb_agg(jsonb_build_object('sku',p.sellpia_sku_code,'option_identity',jsonb_build_array(p.sellpia_product_code,p.sellpia_sku_code)::text,
  'value',c.value,'status',c.status,'generation_id',c.generation_id,'input_fingerprint',c.result_details->>'input_fingerprint',
  'current_input_fingerprint',operations_private.hub_sku_input_fingerprint_v1(p.sellpia_sku_code,''),
  'rule_versions',c.rule_versions,'active_rule_versions',operations_private.hub_base_rule_trace_v1(p.sellpia_sku_code),
  'lineage_valid',operations_private.hub_base_lineage_valid_v1(p.sellpia_sku_code,c.rule_versions)) order by p.sellpia_sku_code),'[]')
 into members from public.sellpia_stock_latest p left join operations_private.hub_calculated_results c on c.sku=p.sellpia_sku_code and c.scope='' and c.field='calculated_base_price'
 where p.sellpia_product_code=p_product;
 n:=jsonb_array_length(members);
 if n=0 or n>1000 then issues:=issues||jsonb_build_array(jsonb_build_object('reason','membership','message','전체 현재 옵션 목록이 없거나 1,000개를 넘습니다.'));end if;
 if (select count(distinct x->>'sku') from jsonb_array_elements(members) x)<>n then issues:=issues||jsonb_build_array(jsonb_build_object('reason','identity','message','옵션 SKU identity 중복'));end if;
 for item in select * from jsonb_array_elements(members) loop
  if nullif(btrim(item->>'sku'),'') is null or item->>'status' is distinct from 'calculated' or item->>'value' is null or (item->>'value')::numeric<0 or (item->>'value')::numeric<>trunc((item->>'value')::numeric) or coalesce((item->>'generation_id')::bigint,0)<1 then
   issues:=issues||jsonb_build_array(jsonb_build_object('sku',item->>'sku','reason','missing','message','유효 옵션 기준가 없음'));
  elsif item->>'input_fingerprint' is null or item->>'input_fingerprint' is distinct from item->>'current_input_fingerprint' then
   issues:=issues||jsonb_build_array(jsonb_build_object('sku',item->>'sku','reason','stale','message','옵션 기준가 입력 변경'));
  elsif item->>'lineage_valid' is distinct from 'true' then
   issues:=issues||jsonb_build_array(jsonb_build_object('sku',item->>'sku','reason','proof','message','active Rule lineage 불명/변경'));
  end if;
 end loop;
 if owner->>'selection'='direct' and not exists(select 1 from jsonb_array_elements(members) m where m->>'sku'=owner->'direct_identity'->>'sku' or m->>'option_identity'=owner->'direct_identity'->>'option_identity') then
  issues:=issues||jsonb_build_array(jsonb_build_object('reason','direct_identity','message','지정 대표 옵션이 현재 membership에 없습니다.'));
 end if;
 body:=jsonb_build_object('product_identity',p_product,'rule',owner-'updated_at'-'updated_by'-'tag_name','contributors',members);
 return body||jsonb_build_object('rule',owner,'issues',issues,'input_fingerprint',encode(extensions.digest(convert_to(body::text,'UTF8'),'sha256'),'hex'));
end $$;

create function operations_private.hub_product_price_read_v1(p_product text)
returns jsonb language plpgsql stable set search_path=pg_catalog as $$
declare input jsonb; stored operations_private.hub_product_price_results%rowtype; status text; history jsonb;
begin
 input:=operations_private.hub_product_price_inputs_v1(p_product);
 select r.* into stored from operations_private.hub_product_price_result_heads h join operations_private.hub_product_price_results r on r.id=h.result_id where h.product_code=p_product;
 if stored.id is not null then history:=to_jsonb(stored);end if;
 status:=case when input->'rule'='null'::jsonb then 'inactive'
  when jsonb_array_length(input->'issues')>0 then case when not exists(select 1 from jsonb_array_elements(input->'issues') i where i->>'reason' not in ('stale','proof')) then 'stale' else 'blocked' end
  when stored.id is null then 'stale' when stored.input_fingerprint<>input->>'input_fingerprint' then 'stale' else stored.status end;
 return input||jsonb_build_object('status',status,'freshness',case when status='calculated' then 'fresh' else status end,
 'value',case when status='calculated' then stored.value end,'generation_id',stored.generation_id,
 'selected_options',case when status='calculated' then stored.proof->'selected_options' else '[]'::jsonb end,
 'stored_history',history,'stage','representative_price','scope','product','output_field','representative_base_price','exclusive_group','representative_price_rule');
end $$;

create function operations_private.hub_sync_product_price_rules_v1(p_skus text[],p_actor text)
returns void language plpgsql set search_path=pg_catalog as $$
declare product text; candidates uuid[]; candidate uuid; existing operations_private.hub_product_price_assignments%rowtype; names text;
begin
 perform pg_advisory_xact_lock(hashtextextended('hub-rule-registry',0));
 for product in select distinct sellpia_product_code from public.sellpia_stock_latest where sellpia_sku_code=any(p_skus) loop
  select array_agg(distinct r.id),string_agg(distinct t.tag_name,', ') into candidates,names
  from operations_private.hub_product_price_rules r join public.product_tags t on t.tag_id=r.tag_id and t.is_active
  join public.sellpia_tag_assignments a on a.tag_id=r.tag_id and a.is_active
  where r.is_active and (a.tag_scope='product' and a.sellpia_product_code=product or a.tag_scope='option' and exists(select 1 from public.sellpia_stock_latest p where p.sellpia_product_code=product and p.sellpia_sku_code=a.sellpia_sku_code));
  if cardinality(candidates)>1 then raise exception '%: 대표가 output 소유권 충돌 (%). 전체 적용을 취소했습니다.',product,names;end if;
  candidate:=candidates[1];select * into existing from operations_private.hub_product_price_assignments where product_code=product;
  if candidate is null then
   delete from operations_private.hub_product_price_assignments where product_code=product;
  elsif existing.rule_id is null then
   if (select selection from operations_private.hub_product_price_rules where id=candidate)='direct' then raise exception '%: 직접지정 대표 옵션을 먼저 명시하세요.',product;end if;
   insert into operations_private.hub_product_price_assignments(product_code,rule_id,updated_by) values(product,candidate,p_actor);
  elsif existing.rule_id<>candidate then
   raise exception '%: 기존 대표가 Rule %를 먼저 해제하세요.',product,existing.rule_id;
  end if;
 end loop;
end $$;

create function operations_private.hub_product_price_v1(p_session_token text,p_action text,p_body jsonb default '{}')
returns jsonb language plpgsql security definer set search_path=pg_catalog set statement_timeout='60s' set lock_timeout='5s' as $$
declare actor jsonb; product text; codes text[]; products text[]; r operations_private.hub_product_price_rules%rowtype;
 a operations_private.hub_product_price_assignments%rowtype; tag public.product_tags%rowtype; input jsonb; direct jsonb;
 result jsonb; item jsonb; target_value numeric; selected jsonb; gid bigint; rid uuid; stored uuid; previous jsonb;
begin
 actor:=operations_private.require_operations_hub_operator_session(p_session_token);
 if jsonb_typeof(p_body) is distinct from 'object' or octet_length(p_body::text)>100000 then raise exception '대표가 요청 객체 오류';end if;
 if p_action='rules' then
  return jsonb_build_object('rules',coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('tag_name',t.tag_name,'stage','representative_price','scope','product','output_field','representative_base_price','exclusive_group','representative_price_rule') order by t.tag_name) from operations_private.hub_product_price_rules x join public.product_tags t on t.tag_id=x.tag_id where x.is_active and t.is_active),'[]'));
 end if;
 if p_action in ('read','inspect','members','materialize') then
  if jsonb_typeof(coalesce(p_body->'skus','[]'))<>'array' or jsonb_typeof(coalesce(p_body->'products','[]'))<>'array' then raise exception 'SKU/상품 배열 오류';end if;
  select coalesce(array_agg(distinct x),'{}') into codes from jsonb_array_elements_text(coalesce(p_body->'skus','[]')) x;
  select coalesce(array_agg(distinct x),'{}') into products from (select x from jsonb_array_elements_text(coalesce(p_body->'products','[]')) x union select sellpia_product_code from public.sellpia_stock_latest where sellpia_sku_code=any(codes)) q;
  if cardinality(codes)>1000 or cardinality(products)>100 then raise exception '요청당 SKU 1,000개/상품 100개 이하로 나누세요.';end if;
  if p_action='members' then return jsonb_build_object('skus',coalesce((select jsonb_agg(distinct p.sellpia_sku_code order by p.sellpia_sku_code) from public.sellpia_stock_latest p join operations_private.hub_product_price_assignments a on a.product_code=p.sellpia_product_code join operations_private.hub_product_price_rules x on x.id=a.rule_id and x.is_active join public.product_tags t on t.tag_id=x.tag_id and t.is_active where p.sellpia_product_code=any(products)),'[]'));
  elsif p_action in ('read','inspect') then return jsonb_build_object('rows',coalesce((select jsonb_agg(operations_private.hub_product_price_read_v1(x) order by x) from unnest(products) x where p_action='inspect' or exists(select 1 from operations_private.hub_product_price_assignments where product_code=x) or exists(select 1 from operations_private.hub_product_price_result_heads where product_code=x)),'[]'));end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('hub-rule-registry',0));
 if p_action='save_rule' then
  if p_body->>'selection' not in ('lowest','lower_middle','direct') or coalesce(length(btrim(p_body->>'name')),0) not between 1 and 200 then raise exception '대표가 이름/선택 방식 오류';end if;
  rid:=nullif(p_body->>'id','')::uuid;
  if rid is not null then
   select * into r from operations_private.hub_product_price_rules where id=rid and is_active for update;
   if r.id is null or r.version is distinct from (p_body->>'version')::integer then raise exception '대표가 Rule version 충돌';end if;
   previous:=to_jsonb(r);
   perform operations_private.hub_product_tag_metadata_update_v1(p_session_token,r.tag_id,p_body->>'name',null,null);
   update operations_private.hub_product_price_rules set selection=p_body->>'selection',version=version+1,updated_by=actor->>'username',updated_at=clock_timestamp() where id=rid returning * into r;
  else
   if exists(select 1 from public.product_tags where is_active and lower(btrim(tag_name))=lower(btrim(p_body->>'name'))) then raise exception '같은 이름의 활성 태그가 있습니다.';end if;
   insert into public.product_tags(tag_name,tag_group,created_by) values(btrim(p_body->>'name'),'가격 수식',actor->>'username') returning * into tag;
   insert into operations_private.hub_product_price_rules(tag_id,selection,updated_by) values(tag.tag_id,p_body->>'selection',actor->>'username') returning * into r;
  end if;
  result:=to_jsonb(r);
 elsif p_action='delete_rule' then
  select * into r from operations_private.hub_product_price_rules where id=(p_body->>'id')::uuid and is_active for update;
  if r.id is null or r.version is distinct from (p_body->>'version')::integer then raise exception '대표가 Rule version 충돌';end if;
  previous:=to_jsonb(r);
  update operations_private.hub_product_price_rules set is_active=false,version=version+1,updated_by=actor->>'username',updated_at=clock_timestamp() where id=r.id returning * into r;
  result:=to_jsonb(r);
 elsif p_action in ('assign','unassign') then
  product:=p_body->>'product_code';
  select array_agg(sellpia_sku_code order by sellpia_sku_code) into codes from public.sellpia_stock_latest where sellpia_product_code=product;
  if coalesce(cardinality(codes),0) not between 1 and 1000 then raise exception '전체 현재 상품 옵션을 확인할 수 없습니다.';end if;
  select * into a from operations_private.hub_product_price_assignments where product_code=product for update;
  if coalesce(a.version,0) is distinct from (p_body->>'expected_assignment_version')::integer then raise exception '상품 대표가 assignment version 충돌';end if;
  previous:=to_jsonb(a);
  if p_action='unassign' then
   select * into r from operations_private.hub_product_price_rules where id=a.rule_id;
   if a.rule_id is null then raise exception '해제할 대표가 assignment 없음';end if;
   update public.sellpia_tag_assignments set is_active=false,updated_at=clock_timestamp() where tag_id=r.tag_id and is_active and (tag_scope='product' and sellpia_product_code=product or tag_scope='option' and sellpia_sku_code=any(codes));
   delete from operations_private.hub_product_price_assignments where product_code=product;
   result:=jsonb_build_object('product_code',product,'status','inactive');
  else
   select * into r from operations_private.hub_product_price_rules where id=(p_body->>'rule_id')::uuid and is_active;
   if r.id is null or not exists(select 1 from public.product_tags where tag_id=r.tag_id and is_active) then raise exception '활성 대표가 Rule 없음';end if;
   if a.rule_id is not null and a.rule_id<>r.id then raise exception '%: 기존 대표가 Rule %를 먼저 해제하세요.',product,a.rule_id;end if;
   direct:=p_body->'direct_identity';
   if r.selection='direct' then
    if jsonb_typeof(direct) is distinct from 'object' or (select count(*) from jsonb_object_keys(direct))<>1 or not (direct ? 'sku' or direct ? 'option_identity') then raise exception '정확한 대표 SKU/옵션 identity 하나 필요';end if;
    if not exists(select 1 from public.sellpia_stock_latest p where p.sellpia_product_code=product and (p.sellpia_sku_code=direct->>'sku' or jsonb_build_array(p.sellpia_product_code,p.sellpia_sku_code)::text=direct->>'option_identity')) then raise exception '지정 옵션이 현재 상품 membership에 없습니다.';end if;
   else direct:=null;end if;
   insert into operations_private.hub_product_price_assignments(product_code,rule_id,direct_identity,updated_by) values(product,r.id,direct,actor->>'username')
   on conflict(product_code) do update set direct_identity=excluded.direct_identity,version=operations_private.hub_product_price_assignments.version+1,updated_at=clock_timestamp(),updated_by=excluded.updated_by returning * into a;
   if not exists(select 1 from public.sellpia_tag_assignments where tag_id=r.tag_id and tag_scope='product' and sellpia_product_code=product and is_active) then
    insert into public.sellpia_tag_assignments(tag_id,tag_scope,sellpia_product_code,reviewer) values(r.tag_id,'product',product,actor->>'username');
   end if;
   perform operations_private.hub_sync_tag_rules(codes,actor->>'username');
   result:=to_jsonb(a);
  end if;
 elsif p_action='materialize' then
  gid:=(p_body->>'generation_id')::bigint;
  if not exists(select 1 from operations_private.hub_calculation_generations where generation_id=gid and created_by=actor->>'username') then raise exception '계산 generation/session 불일치';end if;
  result:='[]';
  foreach product in array products loop
   input:=operations_private.hub_product_price_inputs_v1(product);
   if input->'rule'='null' then continue;end if;
   if p_body->'expected_fingerprints' ? product and p_body->'expected_fingerprints'->>product<>input->>'input_fingerprint' then raise exception '%: 대표가 입력 fingerprint 충돌',product;end if;
   target_value:=null;selected:='[]';
   if jsonb_array_length(input->'issues')=0 then
    if input->'rule'->>'selection'='direct' then
     direct:=input->'rule'->'direct_identity';
     select x into item from jsonb_array_elements(input->'contributors') x where x->>'sku'=direct->>'sku' or x->>'option_identity'=direct->>'option_identity';
     if item is null then input:=jsonb_set(input,'{issues}',jsonb_build_array(jsonb_build_object('reason','direct_identity','message','대표 옵션이 현재 membership에 없습니다.')));
     else target_value:=(item->>'value')::numeric;selected:=jsonb_build_array(item->>'sku');end if;
    else
     select (x->>'value')::numeric into target_value from jsonb_array_elements(input->'contributors') x order by (x->>'value')::numeric,x->>'sku'
      offset case when input->'rule'->>'selection'='lower_middle' then (jsonb_array_length(input->'contributors')-1)/2 else 0 end limit 1;
     select jsonb_agg(x->>'sku' order by x->>'sku') into selected from jsonb_array_elements(input->'contributors') x where (x->>'value')::numeric=target_value;
    end if;
   end if;
   insert into operations_private.hub_product_price_results(product_code,generation_id,value,status,input_fingerprint,proof)
   values(product,gid,target_value,case when target_value is not null then 'calculated' when not exists(select 1 from jsonb_array_elements(input->'issues') i where i->>'reason' not in ('stale','proof')) then 'stale' else 'blocked' end,input->>'input_fingerprint',input||jsonb_build_object('selected_options',selected)) returning id into stored;
   insert into operations_private.hub_product_price_result_heads(product_code,result_id) values(product,stored) on conflict(product_code) do update set result_id=excluded.result_id;
   result:=result||jsonb_build_array(operations_private.hub_product_price_read_v1(product));
  end loop;
  return jsonb_build_object('rows',result);
 else raise exception '지원하지 않는 대표가 작업';end if;
 insert into operations_private.hub_rule_events(action,before_value,after_value,actor) values('product_price_'||p_action,previous,result,actor->>'username');
 return result;
end $$;
create function public.hub_product_price_v1(p_session_token text,p_action text,p_body jsonb default '{}')
returns jsonb language sql security invoker set search_path=pg_catalog as $$
 select operations_private.hub_product_price_v1(p_session_token,p_action,p_body)
$$;
