CREATE OR REPLACE FUNCTION operations_private.hub_sync_tag_rules(p_skus text[], p_actor text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare collision text; changed integer; removed integer; conflict_details text;
begin
 perform pg_advisory_xact_lock(hashtextextended('hub-rule-registry',0));
 if exists(select 1 from pg_class where oid=to_regclass('pg_temp.hub_desired_tag_rules') and relowner<>current_user::regrole) then raise exception '임시 계산 테이블 소유권 오류';end if;
 create temporary table if not exists hub_desired_tag_rules(sku text,rule_id uuid,target_field text,scope text,tag_id uuid,input_origin text) on commit drop;
 create index if not exists hub_desired_tag_rules_lookup on pg_temp.hub_desired_tag_rules(sku,target_field,scope,rule_id);
 truncate pg_temp.hub_desired_tag_rules;
 insert into pg_temp.hub_desired_tag_rules
 select distinct a.sellpia_sku_code,r.id,r.target_field,r.scope,r.tag_id,r.input_origin
 from public.sellpia_tag_assignments a join operations_private.hub_rules r on r.tag_id=a.tag_id and r.is_active
 where a.is_active and a.tag_scope='option' and a.sellpia_sku_code in(select unnest(p_skus))
 union
 select distinct p.sellpia_sku_code,r.id,r.target_field,r.scope,r.tag_id,r.input_origin
 from public.sellpia_stock_latest p
 join public.sellpia_tag_assignments a on a.is_active and a.tag_scope='product' and a.sellpia_product_code=p.sellpia_product_code
 join operations_private.hub_rules r on r.tag_id=a.tag_id and r.is_active
 where p.sellpia_sku_code in(select unnest(p_skus));
 analyze pg_temp.hub_desired_tag_rules;
 select string_agg(format('%s · %s %s · %s',c.sku,coalesce(nullif(c.scope,''),'공통'),c.target_field,c.names),'; ') into conflict_details from (
  select d.sku,d.scope,d.target_field,string_agg(distinct coalesce(t.tag_name,r.name)||' [Rule '||r.name||']',', ') names
  from pg_temp.hub_desired_tag_rules d join operations_private.hub_rules r on r.id=d.rule_id left join public.product_tags t on t.tag_id=d.tag_id
  group by d.sku,d.scope,d.target_field having count(distinct d.rule_id)>1 order by d.sku,d.scope,d.target_field limit 20
 ) c;
 if conflict_details is not null then raise exception '같은 출력의 수식 태그 충돌: %. 기존 적용을 유지하고 전체 요청을 취소했습니다.',conflict_details;end if;
 select string_agg(format('%s · %s %s · 기존 Rule %s / 요청 Rule %s',c.sku,coalesce(nullif(c.scope,''),'공통'),c.target_field,c.old_name,c.new_name),'; ') into conflict_details from (
  select distinct d.sku,d.scope,d.target_field,old.name old_name,new.name new_name
  from pg_temp.hub_desired_tag_rules d join operations_private.hub_rule_assignments a using(sku,target_field,scope)
  join operations_private.hub_rules old on old.id=a.rule_id join operations_private.hub_rules new on new.id=d.rule_id
  where a.rule_id<>d.rule_id and (a.assigned_tag_id is null or exists(select 1 from pg_temp.hub_desired_tag_rules keep where keep.sku=a.sku and keep.rule_id=a.rule_id))
  order by d.sku,d.scope,d.target_field limit 20
 ) c;
 if conflict_details is not null then raise exception '같은 출력의 기존 Rule 충돌: %. 기존 적용을 유지하고 전체 요청을 취소했습니다.',conflict_details;end if;
 select d.sku into collision from pg_temp.hub_desired_tag_rules d where d.input_origin='parent' and not exists(select 1 from operations_private.hub_field_references f where f.child_sku=d.sku and f.rule_id=d.rule_id) limit 1;
 if collision is not null then raise exception '%: 상위 SKU를 참조하는 수식은 종속관계를 먼저 연결하세요.',collision;end if;
 delete from operations_private.hub_rule_assignments a where a.sku in(select unnest(p_skus)) and a.assigned_tag_id is not null and not exists(select 1 from pg_temp.hub_desired_tag_rules d where d.sku=a.sku and d.rule_id=a.rule_id);
 get diagnostics removed=row_count;
 insert into operations_private.hub_rule_assignments(sku,rule_id,target_field,scope,assigned_tag_id,updated_by)
 select d.sku,d.rule_id,d.target_field,d.scope,d.tag_id,p_actor from pg_temp.hub_desired_tag_rules d
 where not exists(select 1 from operations_private.hub_rule_assignments a where a.sku=d.sku and a.target_field=d.target_field and a.scope=d.scope)
 on conflict(sku,target_field,scope) do nothing;
 get diagnostics changed=row_count;
 if changed+removed>0 then perform operations_private.hub_validate_rule_graph();end if;
 perform operations_private.hub_sync_product_price_rules_v1(p_skus,p_actor);
 return changed;
end $function$
;
CREATE OR REPLACE FUNCTION public.hub_tag_catalog_v1(p_session_token text, p_search text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET statement_timeout TO '30s'
AS $function$
declare
 actor jsonb;
 result jsonb;
begin
 actor:=operations_private.require_operations_hub_operator_session(p_session_token);

 select coalesce(jsonb_agg(to_jsonb(row_data) order by lower(row_data.tag_name),row_data.tag_name),'[]'::jsonb)
 into result
 from (
  select
   t.tag_id,
   t.tag_name,
   t.tag_color,
   t.tag_group,
   (select coalesce(jsonb_agg(jsonb_build_object('rule_id',r.id,'rule_name',r.name)||operations_private.hub_output_ownership_v1(r.target_field,r.scope)),'[]'::jsonb) from operations_private.hub_rules r where r.is_active and r.tag_id=t.tag_id) || coalesce((select jsonb_agg(jsonb_build_object('rule_id',r.id,'rule_name',t.tag_name,'stage','representative_price','scope','product','output_field','representative_base_price','exclusive_group','representative_price_rule')) from operations_private.hub_product_price_rules r where r.is_active and r.tag_id=t.tag_id),'[]') as outputs,
   count(a.assignment_id) filter(where a.is_active and a.tag_scope='option')::integer as option_count,
   count(a.assignment_id) filter(where a.is_active and a.tag_scope='product')::integer as product_count,
   (
    select count(*)::integer
    from operations_private.hub_rules r
    where r.is_active and r.tag_id=t.tag_id
   )+ (select count(*)::integer from operations_private.hub_product_price_rules r where r.is_active and r.tag_id=t.tag_id) as rule_count
  from public.product_tags t
  left join public.sellpia_tag_assignments a on a.tag_id=t.tag_id
  where t.is_active
    and (btrim(coalesce(p_search,''))='' or t.tag_name ilike '%'||btrim(p_search)||'%')
  group by t.tag_id,t.tag_name,t.tag_color,t.tag_group
 ) row_data;

 return jsonb_build_object('rows',result);
end $function$
;
