create function operations_private.hub_representative_dependencies_v1(p_sku text,p_source text)
returns text[] language sql stable set search_path=pg_catalog as $$
 with recursive active as (select a.*,r.source_field,r.source_scope,r.input_origin from operations_private.hub_rule_assignments a join operations_private.hub_rules r on r.id=a.rule_id where r.is_active),
 nodes(sku,field,scope) as (
  select s,f,p_source from unnest(operations_private.hub_input_scope_v1(p_sku,p_source)) s cross join (values('platform_registration_price'),('platform_discount_price'),('platform_option_price'),('platform_final_price')) v(f) where p_source<>''
  union select case when a.input_origin='parent' then ref.parent_sku else n.sku end,
   case when a.input_origin='parent' then ref.source_field else a.source_field end,
   case when (case when a.input_origin='parent' then ref.source_field else a.source_field end) like 'platform_%' then coalesce(nullif(ref.source_scope,''),nullif(a.source_scope,''),a.scope) else '' end
  from nodes n join active a on a.sku=n.sku and a.target_field=n.field and a.scope=n.scope
  left join operations_private.hub_field_references ref on ref.child_sku=a.sku and ref.rule_id=a.rule_id
 ), rep_skus as (
  select sku from nodes where field='representative_base_price'
  union select s from unnest(operations_private.hub_input_scope_v1(p_sku,p_source)) s
   join operations_private.hub_work_documents d on d.title='registry-platform:'||p_source and d.kind='formula'
   join operations_private.hub_rules r on r.id::text=d.body->>'registration_rule_id' and r.is_active and r.source_field='representative_base_price'
   where p_source<>'' and not exists(select 1 from active a where a.sku=s and a.scope=p_source and a.target_field='platform_registration_price')
 ) select coalesce(array_agg(distinct p.sellpia_product_code order by p.sellpia_product_code),'{}') from rep_skus s join public.sellpia_stock_latest p on p.sellpia_sku_code=s.sku
$$;
create or replace function operations_private.hub_input_fingerprint_v1(p_sku text,p_source text)
returns text language plpgsql stable set search_path=pg_catalog as $$
declare legacy text; products text[]; proof jsonb;
begin
 legacy:=operations_private.hub_sku_input_fingerprint_v1(p_sku,p_source);
 products:=operations_private.hub_representative_dependencies_v1(p_sku,p_source);
 if cardinality(products)=0 then return legacy;end if;
 select jsonb_agg(jsonb_build_object('product',p,'inputs',operations_private.hub_product_price_inputs_v1(p)->>'input_fingerprint',
  'head',(select jsonb_build_object('id',r.id,'generation',r.generation_id,'fingerprint',r.input_fingerprint,'status',r.status,'value',r.value) from operations_private.hub_product_price_result_heads h join operations_private.hub_product_price_results r on r.id=h.result_id where h.product_code=p)) order by p) into proof from unnest(products) p;
 return encode(extensions.digest(convert_to(jsonb_build_object('sku_proof',legacy,'product_proof',proof)::text,'UTF8'),'sha256'),'hex');
end $$;
create or replace function operations_private.hub_rule_lineage_valid_v1(p_sku text,p_source text,p_versions jsonb)
returns boolean language plpgsql stable set search_path=pg_catalog as $$
declare products text[]; old_versions jsonb; product text; current jsonb;
begin
 if jsonb_typeof(p_versions) is distinct from 'array' then return false;end if;
 products:=operations_private.hub_representative_dependencies_v1(p_sku,p_source);
 if cardinality(products)=0 then return operations_private.hub_sku_rule_lineage_valid_v1(p_sku,p_source,p_versions);end if;
 select coalesce(jsonb_agg(v),'[]') into old_versions from jsonb_array_elements(p_versions) v where not exists(select 1 from operations_private.hub_product_price_rules r where r.id::text=v->>'id');
 if not operations_private.hub_sku_rule_lineage_valid_v1(p_sku,p_source,old_versions) then return false;end if;
 foreach product in array products loop
  current:=operations_private.hub_product_price_read_v1(product);
  if current->>'status'<>'calculated' or not exists(select 1 from jsonb_array_elements(p_versions) v where v->>'id'=current->'rule'->>'rule_id' and v->>'version'=current->'rule'->>'rule_version' and v->>'assignmentVersion'=current->'rule'->>'version') then return false;end if;
 end loop;
 if exists(select 1 from jsonb_array_elements(p_versions) v join operations_private.hub_product_price_rules r on r.id::text=v->>'id' where not exists(select 1 from operations_private.hub_product_price_assignments a where a.product_code=any(products) and a.rule_id=r.id and a.version::text=v->>'assignmentVersion' and r.version::text=v->>'version' and r.is_active)) then return false;end if;
 return true;
end $$;
revoke all on function operations_private.hub_representative_dependencies_v1(text,text) from public,anon,authenticated;
